<script>
 let {snapshots=[]}=$props();
</script>
{#if snapshots.length}<section class="source-snapshots" aria-label="Retained creator sources"><h3>Source and recording proposals</h3><p>Saved research context. Matches, historical metrics and audio permissions remain unverified.</p>{#each snapshots as entry(entry.source.id)}<article><h4>{entry.source.title}</h4><p>{entry.source.creator} · {entry.source.publishedAt||'Date unknown'}</p><a href={entry.source.sourceUrl} target="_blank" rel="noopener noreferrer">Open original source ↗</a>{#if entry.recording}<p><strong>Proposed recording:</strong> {entry.recording.title} · supplied ISRC {entry.recording.suppliedIsrc}</p>{/if}{#if entry.match}<p class="wording">{entry.match.rationale}</p><small>Saved match revision {entry.match.revision} · {entry.match.stage}</small>{/if}{#if entry.workstream}<p>Workstream: {entry.workstream.name}</p>{/if}<details><summary>Supplied observations</summary>{#each entry.source.observations as observation(observation.metric)}<p>{observation.metric}: {observation.value.toLocaleString()} · observed {observation.observedAt||'time unknown'} · {observation.method}</p>{/each}</details></article>{/each}</section>{/if}
<style>
.source-snapshots article{border-left:2px solid #bdcbb4;padding-left:12px;margin:16px 0}.source-snapshots p{line-height:1.6}.source-snapshots h4{margin:4px 0}.wording{white-space:pre-wrap}small{color:#69765f}summary{cursor:pointer}
</style>
